app.get('/users', authenticate, (req, res) => {
  // ... return users
});
```

---

#### 2. No Rate Limiting (OWASP A04: Insecure Design)

There is no rate limiting on any endpoint. This leaves the app vulnerable to brute-force attacks, denial of service, and scraping.

**Recommendation:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' }
});

app.use(limiter);
```

---

### 🟠 High-Severity Issues

#### 3. Missing Security Headers (OWASP A05: Security Misconfiguration)

No security headers are set (CSP, X-Content-Type-Options, HSTS, X-Frame-Options, etc.), making the app vulnerable to clickjacking, MIME-sniffing, and other attacks.

**Recommendation:**
```javascript
const helmet = require('helmet');

// Sets ~15 security headers automatically
app.use(helmet());
```

#### 4. No Input Validation / Body Parsing Configuration (OWASP A03: Injection)

The app doesn't call `app.use(express.json())` with size limits. As the app grows and POST routes are added, there's no foundation for input validation, and the server is vulnerable to large-payload DoS.

**Recommendation:**
```javascript
// Limit body size to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// Use a validation library for route params/query/body
const { query, validationResult } = require('express-validator');

app.get('/users',
  query('page').optional().isInt({ min: 1 }),
  query('limit').optional().isInt({ min: 1, max: 100 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // ...handle request
  }
);
```

#### 5. No CORS Configuration (OWASP A05: Security Misconfiguration)

Without explicit CORS configuration, the behavior depends on the Express version, but there's no intentional policy restricting which origins can access the API.

**Recommendation:**
```javascript
const cors = require('cors');

app.use(cors({
  origin: ['https://your-frontend.com'], // whitelist specific origins
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true
}));
```

---

### 🟡 Medium-Severity Issues

#### 6. Information Disclosure – Server Fingerprinting

Express sets `X-Powered-By: Express` by default, making it easier for attackers to identify the tech stack and target known vulnerabilities.

**Recommendation:**
```javascript
app.disable('x-powered-by');
// Or use helmet() which does this automatically
```

#### 7. No Error Handling Middleware (OWASP A09: Security Logging and Monitoring Failures)

Unhandled errors will produce default Express error pages that may leak stack traces and internal details in production.

**Recommendation:**
```javascript
// Global error handler (place after all routes)
app.use((err, req, res, next) => {
  console.error(`[${new Date().toISOString()}] Error:`, err.message);
  // Never leak stack traces in production
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : err.message
  });
});
```

#### 8. No Request Logging / Audit Trail (OWASP A09: Security Logging and Monitoring Failures)

No logging exists to detect suspicious activity, track access to sensitive data, or support incident response.

**Recommendation:**
```javascript
const morgan = require('morgan');

// Use 'combined' format for production (includes IP, user-agent, etc.)
app.use(morgan('combined'));
```

#### 9. Hardcoded Port / No Environment Configuration

The port is hardcoded and there's no `.env` management, which indicates secrets may also be hardcoded as the app grows.

**Recommendation:**
```javascript
require('dotenv').config();

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

